Definition kfind_word (k : list kentry) (b : expr) (off : Z) (w : nat) : option expr :=
  match List.find (fun K => match K with
                            | KWord a w' _ => (expr_eqb (a_base a) b && Z.eqb (a_off a) off && Nat.eqb w' w)%bool
                            | _ => false end) k with
  | Some (KWord _ _ v) => Some v
  | _ => None
  end.

