Definition kfind_zero (k : list kentry) (b : expr) (off : Z) : option expr :=
  match List.find (fun K => match K with
                            | KZero a _ => (expr_eqb (a_base a) b && Z.eqb (a_off a) off)%bool
                            | _ => false end) k with
  | Some (KZero _ n) => Some n
  | _ => None
  end.
