Definition kfind_fill (k : list kentry) (b : expr) (off : Z) : option (expr * Z) :=
  match List.find (fun K => match K with
                            | KFill a _ _ => (expr_eqb (a_base a) b && Z.eqb (a_off a) off)%bool
                            | _ => false end) k with
  | Some (KFill _ n c) => Some (n, c)
  | _ => None
  end.
