  CSOK E cs R FULL model -> kfind_fill (kn cs) b off = Some (n, c) ->
  flat E (SA b off) (elenZ E n) /\ forall i, 0 <= i < elenZ E n -> FULL (Z_to_bv 64 (estart E (SA b off) + i)) = Some (Z_to_bv 8 c).
