Definition kfind_wr (k : list kentry) (b : expr) (off : Z) : option expr :=
  match List.find (fun K => match K with
                            | KWr a _ => (expr_eqb (a_base a) b && Z.eqb (a_off a) off)%bool
                            | _ => false end) k with
  | Some (KWr _ n) => Some n
  | _ => None
  end.
