Definition kfind_at (k : list kentry) (b : expr) (off : Z) : list kentry :=
  List.filter (fun K => match K with
                        | KWord a _ _ | KZero a _ | KBlob a _ _ | KWr a _ | KFill a _ _ | KUnk a _ => (expr_eqb (a_base a) b && Z.eqb (a_off a) off)%bool
                        | _ => false end) k.
